import json
from pathlib import Path
p=Path('Assignment 2/work/ai_screening')
records=json.loads((p/'records.json').read_text())
D={}
def setd(i,decision,criterion,rationale,confidence='high'):
 assert i not in D
 D[i]=(decision,criterion,rationale,confidence)
def inc(i,r,c='high'):setd(i,'Include','Potentially eligible',r,c)
def exc(i,r,criterion='EC1',c='high'):setd(i,'Exclude',criterion,r,c)
def unc(i,r):setd(i,'Uncertain','Insufficient evidence',r,'low')
