# Missing/truncated text is not silently treated as a full-abstract read.
for i,r in enumerate(records):
 if i in D:continue
 a=(r.get('abstract') or '').strip()
 if not a:
  if i in {57,104}:
   exc(i,'The title explicitly concerns tunnel/slope mechanical stability rather than stability of machine-learning explanations; no abstract was supplied.','EC5')
  elif i==180:
   exc(i,'The title explicitly limits the application to EEG emotion recognition, a signal modality; no tabular task or abstract is supplied.','EC2',c='medium')
  elif i==194:
   exc(i,'The title concerns core stability of Shapley values in cooperative games, not SHAP/LIME feature-attribution explanations; no abstract supplied.','EC3')
  else:
   unc(i,'No abstract supplied. The title ('+r['title']+') does not establish all three requirements: tabular task, SHAP/LIME family, and separately assessed explanation stability/uncertainty.')
 elif a.endswith('...'):
  if i==28:
   exc(i,'The title and stored abstract identify NLP spam-message classification using contextual/obfuscated text, with no tabular task stated.','EC2',c='medium')
  else:
   unc(i,'The stored abstract is truncated. It introduces '+r['title']+' but does not provide enough outcome/method evidence to judge separately assessed SHAP/LIME explanation stability; obtain the complete abstract.')
 else:
  raise RuntimeError('Unreviewed full abstract '+str(i)+' '+r['id'])
out=[]
for i,r in enumerate(records):
 d,c,why,confidence=D[i]
 out.append(dict(id=r['id'],decision=d,criterion=c,rationale=why,evidence_basis='Stored title and abstract' if r.get('abstract') else 'Title only',confidence=confidence))
assert len(out)==197 and len({r['id'] for r in out})==197
assert {r['id'] for r in out}=={r['id'] for r in records}
(p/'saif_decisions.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')
from collections import Counter
print(Counter(r['decision'] for r in out));print(Counter(r['criterion'] for r in out))
